    WhatsAppConnectionController_connect: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description QR code emitido; a conexão fica `connecting`. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description O número aguarda a leitura do QR code.
                         * @example connecting
                         * @enum {string}
                         */
                        status: "connecting";
                        /**
                         * @description QR code em data URL PNG, para ler no WhatsApp Business. Chame a rota de novo para um QR code atualizado.
                         * @example data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAA...
                         */
                        qrCode: string;
                    };
                };
            };
            /** @description Sem token, token inválido ou expirado, ou usuário removido. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
            /** @description O perfil da sessão não tem acesso (Barbeiro). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
            /** @description O número da barbearia já está conectado. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
            /** @description O conector de WhatsApp não respondeu, respondeu com erro ou não devolveu QR code. */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
        };
    };
    WhatsAppConversationsController_listWaiting: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Conversas aguardando humano; lista vazia quando não há. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Conversas pausadas, da transferência mais antiga para a mais nova. */
                        conversations: {
                            /**
                             * Format: uuid
                             * @description Id do cliente; use na rota de reativação.
                             * @example 4f1c2d3e-5a6b-4c7d-8e9f-0a1b2c3d4e5f
                             */
                            clientId: string;
                            /** @example João Silva */
                            clientName: string;
                            /**
                             * @description Telefone do cliente em E.164, para achar a conversa no app.
                             * @example +5511987654321
                             */
                            phone: string;
                            /**
                             * @description Por que o bot transferiu: `requested` (o cliente pediu um atendente) ou `not_understood` (duas falhas seguidas de entendimento).
                             * @example requested
                             * @enum {string}
                             */
                            reason: "requested" | "not_understood";
                            /**
                             * Format: date-time
                             * @description Quando o bot transferiu a conversa (UTC).
                             * @example 2026-09-29T14:00:00.000Z
                             */
                            pausedAt: string;
                            /**
                             * Format: date-time
                             * @description Última mensagem do cliente ou da equipe (UTC). O bot volta sozinho depois de `WHATSAPP_HANDOFF_RESUME_HOURS` horas (padrão 12) sem mensagens.
                             * @example 2026-09-29T14:30:00.000Z
                             */
                            lastActivityAt: string;
                        }[];
                    };
                };
            };
            /** @description Sem token, token inválido ou expirado, ou usuário removido. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
            /** @description O perfil da sessão não tem acesso (Barbeiro). */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
        };
    };
