    EvolutionWebhookController_receive: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description Evento da Evolution API, em minúsculas com ponto.
                     * @example connection.update
                     */
                    event: string;
                    /**
                     * @description Nome da instância, que é o id da barbearia (AD-011).
                     * @example 0b9f7d8e-8a55-4c1c-9d51-6f2f3d1f0a11
                     */
                    instance: string;
                    /**
                     * @description Dados do evento; em `connection.update`, traz `state`; em `messages.upsert`, a mensagem (`key`, `pushName`, `messageTimestamp`).
                     * @example {
                     *       "state": "close",
                     *       "statusReason": 401
                     *     }
                     */
                    data?: unknown;
                } & {
                    [key: string]: unknown;
                };
            };
        };
        responses: {
            /** @description Evento recebido (aplicado ou ignorado). */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Payload inválido; `errors` aponta cada campo. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example Dados inválidos. */
                        message: string;
                        errors: {
                            /**
                             * @description Caminho do campo inválido, separado por ponto.
                             * @example openingHours.monday.opensAt
                             */
                            field: string;
                            /** @example Informe o horário no formato HH:mm, entre 00:00 e 23:59. */
                            message: string;
                        }[];
                    };
                };
            };
            /** @description Header `authorization` ausente ou com outro segredo. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Mensagem para o usuário final. */
                        message: string;
                    };
                };
            };
        };
    };
